# Eisai Widget Installation Script (Base64 Safe)
$dokPath = [Environment]::GetFolderPath('MyDocuments')
$dest = "$dokPath\Rainmeter\Skins\Eisai"

if (-not (Test-Path $dest)) {
    New-Item -ItemType Directory -Path $dest -Force | Out-Null
}

# Determine Campus ID (default to 1)
$cid = if ($env:EisaiCampusId) { $env:EisaiCampusId } else { "1" }
Write-Host "Installing for Campus ID: $cid"

# Update fetching script (ASCII safe)
$updateScriptContent = @'
$dataPath = "C:\EisaiData"
if (-not (Test-Path $dataPath)) { New-Item -ItemType Directory -Path $dataPath -Force | Out-Null }

try {
    $wc = New-Object System.Net.WebClient
    $wc.Encoding = [System.Text.Encoding]::UTF8
    # Add timestamp to prevent caching
    $ts = Get-Date -Format "yyyyMMddHHmmss"
    $content = $wc.DownloadString("https://eisai-api.vercel.app/api/widget?campusId=__CID__&format=text&t=$ts")
    
    [System.IO.File]::WriteAllText("$dataPath\data.ini", $content, [System.Text.Encoding]::Unicode)
    Write-Host "Data updated successfully"
} catch {
    Write-Host "Error updating data: $_"
}
'@

# Inject Campus ID
$updateScriptContent = $updateScriptContent -replace "__CID__", $cid
[System.IO.File]::WriteAllText("$dest\Update.ps1", $updateScriptContent, [System.Text.Encoding]::ASCII)

# Write Final.ini from Base64 to ensure correct encoding
$finalIniBase64 = ""
[System.IO.File]::WriteAllBytes("$dest\Final.ini", [System.Convert]::FromBase64String($finalIniBase64))
Write-Host "Created Final.ini"

# Initial data fetch
powershell -ExecutionPolicy Bypass -File "$dest\Update.ps1"

# Try to activate the skin automatically
$rmPath = "$env:ProgramFiles\Rainmeter\Rainmeter.exe"
if (-not (Test-Path $rmPath)) {
    $rmPath = "${env:ProgramFiles(x86)}\Rainmeter\Rainmeter.exe"
}

if (Test-Path $rmPath) {
    Write-Host "Activating skin..."
    Start-Process -FilePath $rmPath -ArgumentList "!ActivateConfig", "`"Eisai`"", "`"Final.ini`""
    Write-Host "Skin activated!"
}
